package at.gregor.layermaxxing

import org.json.JSONObject

/**
 * 7.9.13, grid_version 6: THE ground contract, read from the very file the server validates with
 * (server/app/geometry/island_ground.json, packaged as a Java resource, generated by server/tools/island_ground.py from
 * the painted sprites and the painted terrain). Like in Clash of Clans a piece occupies only its GROUND: one rectangle
 * of lattice cells (the plate it stands on). Roofs, crowns and towers may cover other pieces on screen (the renderer
 * sorts by the ground line); only grounds may not share a cell. The touch target is the drawn sprite, not the ground.
 *
 * The terrain's zones (L meadow, B beach, S shore sand, R rock, W water) decide where a ground may lie: a normal piece's
 * whole ground on meadow inside the land stage's build ellipse ([IslandGrid.buildable]); the harbour's rowboat on the
 * beach; a pier with its root on the beach, its head and berth over open water. Drawing, targets, green/✓ and the server
 * use this one decision. Version 5 ([IslandMasks]) is kept unchanged for servers that still run it.
 */
internal object IslandGround {
    /** [ground] / [sea] = (x0, y0, x1, y1) inclusive offsets from the spot; [sea] only for a pier (harbour 1..3). */
    data class Shape(val size: Float, val ground: List<Int>, val sea: List<Int>?)
    data class Coast(val outline: List<Pair<Float, Float>>, val rocks: List<Triple<Float, Float, Float>>)
    const val RESOURCE = "island_ground.json"

    private class Data(val zones: List<String>, val pieces: Map<String, List<Shape>>, val berth: List<Int>, val coast: Coast, val version: Int)
    private val data: Data by lazy { parse(load(RESOURCE)) }
    private val constantData: Data by lazy { parse(load("island_constant_ground.json")).also { require(it.version == 8) } }
    private fun contract(version: Int) = if (version == PlacementRule.CONSTANT) constantData else data

    private fun load(resource: String): String =
        (IslandGround::class.java.classLoader?.getResourceAsStream(resource) ?: error("$resource fehlt im Paket"))
            .use { it.readBytes().toString(Charsets.UTF_8) }

    private fun parse(text: String): Data {
        val root = JSONObject(text)
        fun ints(a: org.json.JSONArray) = (0 until a.length()).map { a.getInt(it) }
        val all = root.getJSONObject("pieces")
        val pieces = all.keys().asSequence().associateWith { key ->
            val lands = all.getJSONObject(key).getJSONArray("lands")
            (0 until lands.length()).map { l ->
                val e = lands.getJSONObject(l)
                Shape(e.getDouble("size").toFloat(), ints(e.getJSONArray("ground")), e.optJSONArray("sea")?.let(::ints))
            }
        }
        val zones = root.getJSONArray("zones").let { a -> (0 until a.length()).map { a.getString(it) } }
        val c = root.getJSONObject("coast")
        val outline = c.getJSONArray("outline").let { a -> (0 until a.length()).map { a.getJSONArray(it).let { p -> p.getDouble(0).toFloat() to p.getDouble(1).toFloat() } } }
        val rocks = c.getJSONArray("rocks").let { a -> (0 until a.length()).map { a.getJSONArray(it).let { p -> Triple(p.getDouble(0).toFloat(), p.getDouble(1).toFloat(), p.getDouble(2).toFloat()) } } }
        return Data(zones, pieces, ints(root.getJSONArray("berth")), Coast(outline, rocks), root.getInt("version"))
    }

    fun version(): Int = data.version
    fun keys(): Set<String> = data.pieces.keys
    /** Where a ship moors in front of a pier head: one cell towards the viewer (open water). */
    val BERTH: List<Int> get() = data.berth
    /** The painted island's solid outline and the rocks in the water (box fractions at land scale 1). */
    val coast: Coast get() = data.coast

    /** The zone of lattice cell (i, j); outside 0..20 it is water. */
    fun zone(i: Int, j: Int): Char = if (i in 0..IslandGrid.STEPS && j in 0..IslandGrid.STEPS) data.zones[j][i] else 'W'
    fun zone(c: List<Int>): Char = zone(c[0], c[1])
    /** May a normal piece's ground lie on (i, j) on this land stage? Meadow inside the build ellipse. */
    fun meadow(i: Int, j: Int, land: Int) = zone(i, j) == 'L' && IslandGrid.buildable(i, j, land)

    fun shape(key: String, land: Int, version: Int = 6): Shape = contract(version).pieces.getValue(key)[land.coerceIn(0, 5)]
    private fun rect(r: List<Int>?, spot: List<Int>): Set<List<Int>> = r?.let {
        buildSet { for (x in r[0]..r[2]) for (y in r[1]..r[3]) add(listOf(spot[0] + x, spot[1] + y)) }
    }.orEmpty()
    /** The ground rectangle of [key] standing at [spot] (without a pier's head over the water). */
    fun ground(key: String, land: Int, spot: List<Int>, version: Int = 6): Set<List<Int>> = rect(shape(key, land, version).ground, spot)
    /** A pier's head over the water (empty for every other piece). */
    fun sea(key: String, land: Int, spot: List<Int>, version: Int = 6): Set<List<Int>> = rect(shape(key, land, version).sea, spot)
    /** Everything the piece occupies: its ground and a pier's head. */
    fun cells(key: String, land: Int, spot: List<Int>, version: Int = 6): Set<List<Int>> = ground(key, land, spot, version) + sea(key, land, spot, version)

    /** Why the piece's whole ground does not fit its zone at [spot] (null = it does); the server's ground_error. */
    fun landProblem(key: String, land: Int, spot: List<Int>, harbour: Boolean, version: Int = 6): String? {
        if (spot.size != 2 || spot[0] !in 0..IslandGrid.STEPS || spot[1] !in 0..IslandGrid.STEPS) return "Außerhalb der Insel"
        val ground = ground(key, land, spot, version)
        val sea = sea(key, land, spot, version)
        if (harbour) {
            if (ground.any { zone(it) != 'B' })
                return if (sea.isNotEmpty()) "Der Steg wächst vom Strand ins Wasser – sein Fuß gehört auf den Strand"
                else "Das Ruderboot liegt am Strand – nur auf dem Sand der Bucht"
            if (sea.isNotEmpty() && (sea.any { zone(it) != 'W' } || zone(spot[0] + BERTH[0], spot[1] + BERTH[1]) != 'W'))
                return "Der Steg braucht davor offenes Wasser ohne Felsen"
            return null
        }
        if (ground.all { meadow(it[0], it[1], land) }) return null
        val zones = ground.map { zone(it) }.toSet()
        return when {
            'B' in zones -> "Am Strand liegt nur der Hafen – Gebäude stehen auf der Wiese"
            'R' in zones -> "Dort liegen Felsen – der Boden passt hier nicht"
            else -> "Passt hier nicht ganz auf die Insel – der Boden ragt über den Rand"
        }
    }

    private val lattice: List<List<Int>> by lazy { buildList { for (j in 0..IslandGrid.STEPS) for (i in 0..IslandGrid.STEPS) add(listOf(i, j)) } }
    private val meadowByLand = Array(6) { land -> lazy { IslandGrid.buildableCells(land).filter { zone(it) == 'L' } } }
    /** Candidate spots: every lattice cell for the harbour (its zones decide), the meadow cells for everything else. */
    fun spots(land: Int, harbour: Boolean): List<List<Int>> = if (harbour) lattice else meadowByLand[land.coerceIn(0, 5)].value
    /** Every spot where a harbour of this stage fits with its ground (other pieces ignored): its snap spots. */
    fun harbourSpots(stage: Int, land: Int, version: Int = 6): List<List<Int>> {
        val key = IslandMasks.buildingKey(IsleBuilding.HARBOUR, stage)
        return lattice.filter { landProblem(key, land, it, harbour = true, version = version) == null }
    }

    /**
     * Where a ship moors at a harbour of [stage] standing at [spot]: in front of a pier head; for the rowboat on the
     * beach the first open water straight in front of it (the walk from the boat down to the water line).
     */
    fun berthCell(spot: List<Int>, stage: Int, version: Int = 6): List<Int> {
        if (stage > 0 && version != PlacementRule.CONSTANT) return listOf(spot[0] + BERTH[0], spot[1] + BERTH[1])
        var y = spot[1] + 1
        while (y <= IslandGrid.STEPS + 1 && zone(spot[0], y) != 'W') y++
        return listOf(spot[0], y)
    }
}
